import { Flow } from "@smthrs/flow"
import { Node } from "@smthrs/plan"
import { CiJob } from "@smthrs/sandbox"
import { Schema } from "effect"

const auditJob = CiJob.make("backpressure-audit", {
  steps: [
    { name: "uphill-check", run: "uphill check" },
    { name: "uphill-report", run: "uphill --compact" }
  ]
})

export default Flow.make("backpressure-audit", {
  description: "Score backpressure metrics and publish a Lighthouse audit report",
  payload: { target: CiJob.Target },
  success: Schema.Struct({ audit: CiJob.Result }),
  body: Node.capture({}, ({ target }) => Node.all({ audit: auditJob.call(target) }))
})
